// ============================================================
// NODE: Cek Status Sesi PIN
// State machine login berbasis PIN, sesi disimpan di Static Data.
// Perbaikan: PIN via env, pruning sesi kedaluwarsa, sliding session.
// ============================================================

// --- KONFIGURASI ---
const VALID_PIN = (typeof process !== 'undefined' && process.env && process.env.STOK_PIN)
  ? String(process.env.STOK_PIN)
  : '0000';                 // fallback; set env STOK_PIN untuk produksi
const SESSION_MINUTES = 60; // durasi sesi (menit)
const SLIDING_SESSION = true; // true = perpanjang sesi tiap aktivitas
// --------------------

const webhookBody = $('WhatsApp Webhook').first().json.body;
const userMessage = (webhookBody.message || webhookBody.pesan || '').trim();
const sender      = webhookBody.sender || webhookBody.username || '';
const senderClean = sender.replace('@s.whatsapp.net', '').replace('@c.us', '');

const staticData = $getWorkflowStaticData('global');
if (!staticData.sessions) staticData.sessions = {};
const sessions   = staticData.sessions;
const now        = Date.now();
const SESSION_MS = SESSION_MINUTES * 60 * 1000;

// --- Pruning: hapus sesi yang sudah kedaluwarsa (cegah static data membengkak) ---
for (const key of Object.keys(sessions)) {
  const s = sessions[key];
  const loginExpired   = s.loginTime && (now - s.loginTime) >= SESSION_MS;
  const stalePinWait   = s.waitingForPin && s.createdAt && (now - s.createdAt) >= (10 * 60 * 1000);
  if ((!s.loginTime && !s.waitingForPin) || loginExpired || stalePinWait) {
    delete sessions[key];
  }
}

const sessionKey  = senderClean;
const userSession = sessions[sessionKey] || null;
const isLoggedIn  = userSession && userSession.loginTime && (now - userSession.loginTime) < SESSION_MS;

const isLoginCommand  = userMessage.toUpperCase() === 'LOGIN';
const isWaitingForPin = userSession && userSession.waitingForPin === true;
const isPinInput      = isWaitingForPin && !isLoginCommand;

// [CASE 1] Sudah login & sesi valid -> teruskan ke AI
if (isLoggedIn && !isLoginCommand) {
  if (SLIDING_SESSION) {
    sessions[sessionKey] = { waitingForPin: false, loginTime: now };
  }
  return [{ json: {
    state: 'AUTHENTICATED',
    userMessage, sender, senderClean,
    session: webhookBody.session,
    botNumber: webhookBody.botNumber
  }}];
}

// [CASE 2] Ketik LOGIN -> minta PIN
if (isLoginCommand) {
  sessions[sessionKey] = { waitingForPin: true, loginTime: null, createdAt: now };
  return [{ json: {
    state: 'WAITING_PIN',
    replyMessage: '🔒 Silakan masukkan PIN Anda untuk mengakses data:',
    sender, senderClean
  }}];
}

// [CASE 3] Sedang menunggu PIN -> validasi
if (isPinInput) {
  if (userMessage === VALID_PIN) {
    sessions[sessionKey] = { waitingForPin: false, loginTime: now };
    return [{ json: {
      state: 'LOGIN_SUCCESS',
      replyMessage: `✅ *Login berhasil!*\n\nSelamat datang di Asisten Stok Sayur 🥬\nSesi Anda aktif selama ${SESSION_MINUTES} menit.\n\nSilakan tanyakan data stok, harga, atau informasi lainnya.`,
      sender, senderClean
    }}];
  } else {
    delete sessions[sessionKey];
    return [{ json: {
      state: 'WRONG_PIN',
      replyMessage: '❌ PIN salah. Silakan ketik *LOGIN* untuk mencoba lagi.',
      sender, senderClean
    }}];
  }
}

// [CASE 4] Belum login & tidak ketik LOGIN
return [{ json: {
  state: 'NOT_LOGGED_IN',
  replyMessage: '🔐 Anda belum login.\n\nKetik *LOGIN* untuk memulai, lalu masukkan PIN Anda.',
  sender, senderClean
}}];

// Gabungkan data tampilan (FORMATTED) + formula (untuk link foto).
const formatted  = $('Ambil Data Sheets').first().json;   // FORMATTED_VALUE
let formula = {};
try { formula = $('Ambil Link Foto').first().json; } catch (e) { formula = {}; }
const pinData     = $('Cek Status Sesi PIN').first().json;
const webhookBody = $('WhatsApp Webhook').first().json.body;
const userMessage = pinData.userMessage || '';
const chatId      = pinData.sender || null;
const senderClean = pinData.senderClean || null;

function extractFileId(cell) {
  if (!cell || typeof cell !== 'string') return null;
  let m = cell.match(/\/d\/([-\w]{20,})/);     // HYPERLINK .../file/d/ID/view
  if (m) return m[1];
  m = cell.match(/[?&]id=([-\w]{20,})/);         // IMAGE .../uc?...id=ID
  if (m) return m[1];
  m = cell.match(/([-\w]{25,})/);                // fallback token panjang
  return m ? m[1] : null;
}

let dataText = 'DATA TIDAK TERSEDIA';
const photoMap = [];
try {
  const rows  = (formatted && formatted.values) ? formatted.values : [];
  const fRows = (formula && formula.values) ? formula.values : [];
  if (rows.length > 0) {
    const headers = rows[0] || [];
    const lc = headers.map(h => String(h).toLowerCase());
    let fotoIdx  = lc.findIndex(h => h.includes('foto'));
    if (fotoIdx < 0) fotoIdx = headers.length - 1;
    const sayurIdx = lc.findIndex(h => h.includes('sayur'));
    let beratIdx   = lc.findIndex(h => h.includes('berat') || h.includes('kg'));
    let waktuIdx   = lc.findIndex(h => h.includes('time') || h.includes('stamp') || h.includes('tanggal'));
    if (waktuIdx < 0) waktuIdx = 0;
    const dataRows = rows.slice(1);

    let t = 'DATA STOK SAYUR PASAR TRADISIONAL:\n';
    t += 'ID | ' + headers.filter((_, i) => i !== fotoIdx).join(' | ') + ' | Foto\n';
    t += '-'.repeat(60) + '\n';

    dataRows.forEach((row, i) => {
      const id = i + 1;
      const fCell = (fRows[i + 1] || [])[fotoIdx] || '';
      const fileId = extractFileId(fCell);
      const cols = headers
        .map((_, c) => {
          if (c === fotoIdx) return null;
          let v = row[c];
          if (v === undefined || v === null || String(v).trim() === '') {
            v = (c === sayurIdx) ? '(tanpa nama)' : 'kosong';
          }
          return v;
        })
        .filter(v => v !== null);
      t += id + ' | ' + cols.join(' | ') + ' | ' + (fileId ? 'Ada' : '-') + '\n';
      if (fileId) {
        photoMap.push({
          id, fileId,
          sayur: sayurIdx >= 0 ? (row[sayurIdx] || '') : '',
          berat: beratIdx >= 0 ? (row[beratIdx] || '') : '',
          waktu: waktuIdx >= 0 ? (row[waktuIdx] || '') : ''
        });
      }
    });
    dataText = t;
  } else if (formatted && formatted.error) {
    dataText = 'GAGAL MENGAMBIL DATA: ' + (formatted.error.message || 'Error tidak diketahui');
  }
} catch (e) {
  dataText = 'ERROR PARSING DATA: ' + e.message;
}

return [{
  json: {
    userMessage,
    sheetsContext: dataText,
    chatId, senderClean,
    photoMap,
    session: webhookBody.session,
    botNumber: webhookBody.botNumber
  }
}];

// Bersihkan output AI + ekstrak penanda [[SEND_PHOTOS: ...]]
let output = '';
try { output = $input.first().json.output || ''; } catch (e) { output = ''; }
output = String(output).trim();

let photoIds = [];
const m = output.match(/\[\[\s*SEND_PHOTOS\s*:\s*([0-9,\s]+)\]\]/i);
if (m) {
  photoIds = m[1].split(',').map(s => parseInt(s.trim(), 10)).filter(n => !isNaN(n));
  output = output.replace(m[0], '').trim();
}

if (!output) output = 'Baik, permintaan Anda saya proses.';
const MAX_LEN = 3900;
if (output.length > MAX_LEN) output = output.slice(0, MAX_LEN) + '\n\n…(pesan dipotong)';

const chatId      = $('Format Data').first().json.chatId || null;
const senderClean = $('Format Data').first().json.senderClean || null;

return [{
  json: {
    safeOutput: output,
    chatId, senderClean,
    hasWhatsApp: senderClean !== null && senderClean !== '',
    photoIds
  }
}];

// Susun SATU pesan teks berisi link Drive (paket gratis tidak bisa kirim media).
const photoIds    = $json.photoIds || [];
const senderClean = $('Format Data').first().json.senderClean || $json.senderClean || '';
const photoMap    = $('Format Data').first().json.photoMap || [];
const byId = {};
photoMap.forEach(p => { byId[p.id] = p; });

const MAX_PHOTOS = 25; // pengaman
const ids = photoIds.slice(0, MAX_PHOTOS);

const lines = [];
let n = 0;
for (const id of ids) {
  const p = byId[id];
  if (!p) continue;
  n++;
  const link  = 'https://drive.google.com/file/d/' + p.fileId + '/view';
  const label = (p.sayur || 'Foto')
    + (p.berat ? ' (' + p.berat + ' Kg)' : '')
    + (p.waktu ? ' — ' + p.waktu : '');
  lines.push(`${n}. ${label}\n${link}`);
}

let message;
if (lines.length === 0) {
  message = 'Maaf, foto untuk permintaan itu tidak ditemukan.';
} else {
  message = '📷 Link foto yang diminta:\n\n' + lines.join('\n\n');
}

const MAX_LEN = 3900;
if (message.length > MAX_LEN) message = message.slice(0, MAX_LEN) + '\n\n…(daftar dipotong)';

return [{ json: { target: senderClean, message } }];
